div.script:

const questions = [
  {
    q: "What does Mr. Whetzel teach?",
    options: ["Computer", "Math", "Science", "History"],
    answer: 0
  },
  {
    q: "What does Ms. Rutland teach?",
    options: ["Art and Music", "Sewing and Cooking", "Physical Education", "Spanish"],
    answer: 1
  },
  {
    q: "Who is the Principal?",
    options: ["Mr. Whetzel", "Mr. F", "Mr. Colburn", "Mr. Davis"],
    answer: 2
  },
  {
    q: "What does Mr. F teach?",
    options: ["Biology", "Engineering", "English", "Drama"],
    answer: 1
  },
  {
    q: "How much is one lunch meal?",
    options: ["$2.50", "$3.00", "$2.75", "$3.25"],
    answer: 2
  }
];

let currentIdx = 0;
let score = 0;
let bestScore = parseInt(localStorage.getItem('tq_best') || '0', 10);
let acceptAnswers = true;

const quizCard = document.getElementById('quizCard');
const questionProgress = document.getElementById('questionProgress');
const scoreText = document.getElementById('scoreText');
const questionText = document.getElementById('questionText');
const optionsGrid = document.getElementById('optionsGrid');

function loadQuestion() {
  acceptAnswers = true;
  const current = questions[currentIdx];

  questionProgress.textContent = `QUESTION ${currentIdx + 1} OF ${questions.length}`;
  questionText.textContent = current.q;
  optionsGrid.innerHTML = '';

  current.options.forEach((opt, index) => {
    const btn = document.createElement('button');
    btn.className = 'option-btn';
    btn.textContent = opt;
    btn.onclick = () => checkAnswer(index, btn);
    optionsGrid.appendChild(btn);
  });
}

function checkAnswer(selectedIdx, btn) {
  if (!acceptAnswers) return;
  acceptAnswers = false;

  const current = questions[currentIdx];
  const allBtns = optionsGrid.children;

  if (selectedIdx === current.answer) {
    btn.classList.add('correct');
    score++;
    scoreText.textContent = score;
  } else {
    btn.classList.add('wrong');
    allBtns[current.answer].classList.add('correct');
  }

  setTimeout(() => {
    currentIdx++;
    if (currentIdx < questions.length) {
      loadQuestion();
    } else {
      showResults();
    }
  }, 1200);
}

function showResults() {
  if (score > bestScore) {
    bestScore = score;
    localStorage.setItem('tq_best', bestScore.toString());
  }

  quizCard.innerHTML = `
    <div class="results-box">
      <h2 style="margin:0; font-size:1.8rem; font-weight:900;">QUIZ COMPLETE!</h2>
      <div class="score-big">${score} / ${questions.length}</div>
      <p style="margin:0; color:#94a3b8; font-size:0.95rem;">Personal Best: ${bestScore} / ${questions.length}</p>
      <button class="btn-restart" onclick="restartQuiz()">TRY AGAIN</button>
    </div>
  `;
}

function restartQuiz() {
  currentIdx = 0;
  score = 0;
  scoreText.textContent = '0';

  quizCard.innerHTML = `
    <div class="quiz-header">
      <span id="questionProgress">QUESTION 1 OF 5</span>
      <span>SCORE: <span id="scoreText" style="color:#a855f7;">0</span></span>
    </div>
    <div class="question-text" id="questionText">Loading...</div>
    <div class="options-grid" id="optionsGrid"></div>
  `;

  // Re-bind dynamic references
  document.getElementById('scoreText').textContent = score;
  loadQuestion();
}

// Initialize First Question
loadQuestion();
